void kernel_correlation(double float_n, double data[32][28], double corr[28][28], double mean[28], double stddev[28]) {
    // compute mean
    for (int j=0;j<28;j++) {
        double sum = 0.0;
        for (int i=0;i<32;i++) {
            sum += data[i][j];
        }
        mean[j] = sum / float_n;
    }

    // compute stddev
    for (int j=0;j<28;j++) {
        double acc = 0.0;
        for (int i=0;i<32;i++) {
            double diff = data[i][j] - mean[j];
            acc += diff * diff;
        }
        stddev[j] = sqrt(acc / float_n);
    }

    // compute corr
    for (int i=0;i<28;i++) {
        for (int j=0;j<28;j++) {
            double sum = 0.0;
            for (int k=0;k<32;k++) {
                sum += (data[k][i] - mean[i]) * (data[k][j] - mean[j]);
            }
            corr[i][j] = sum / (float_n * stddev[i] * stddev[j]);
        }
    }
}

